int n,m;
int a[N],ans,sum[N];
int main()
{
    n=read(),m=read();
    for(int i=1;i<=n;i++)a[i]=read();
    a[++n]=m;
    for(int i=1;i<=n;i++)
    if(i&1) sum[i]=sum[i-1]+(a[i]-a[i-1]);
    else sum[i]=sum[i-1];

    ans=sum[n];

    for(int i=1;i<n;i++)
    if(i&1)
    {
        if(a[i]+1<a[i+1])
        {
            int ret=sum[i];
            ret+=a[i+1]-a[i]-1;
            int tmp=m-a[i+1]-sum[n]+sum[i+1];
            ret+=tmp;
            ans=max(ans,ret);
        }
        if(a[i]-1>a[i-1])
        {
            int ret=sum[i]-1;
            int tmp=m-a[i]-sum[n]+sum[i];
            ret+=tmp;
            ans=max(ans,ret);
        }
    }
    cout<<ans<<endl;
}

