    for (int i = 0; i < q; i++) {
        int l, r;
        scanf("%d %d", &l, &r);
        l--;
        r--;
        queries[i] = mp(mp(r, l), i);
    }
    sort(queries, queries + q);
    int j = 0;
    for (int i = 0; i < n; i++) {
        if (b[a[i]].X == 0 && b[a[i]].Y == 0) {
            b[a[i]].Y = i;
            modify(i, mp(-1, a[i]));
            b[a[i]].X = -1;
        } else {
            modify(b[a[i]].Y, mp(MOD, MOD));
            b[a[i]].X = b[a[i]].Y;
            b[a[i]].Y = i;
            modify(i, mp(b[a[i]].X, a[i]));
        }
        while (j < q && queries[j].X.X == i) {
            ll l = queries[j].X.Y;
            ll num = queries[j].Y;

            pii mag = query(l, i+1);
            //cout << l << " " << i << " " << mag.X << " " << mag.Y << endl;
            if (mag < mp(l-1, MOD))
                res[num] = mag.Y;
            j++;
        }
    }
    for (int i = 0; i < q; i++) {
        printf("%d\n", res[i]);
    }
    return 0;
}

