import random
import sys


# sys.setrecursionlimit(10**8)设置最大递归次数


class FastIO:
    def __init__(self):
        self.random_seed = random.randint(0, 10 ** 9 + 7)
        return

    @staticmethod
    def read_ints():
        return map(int, sys.stdin.readline().strip().split())

    @staticmethod
    def read_list_ints():
        return list(map(int, sys.stdin.readline().strip().split()))

    @staticmethod
    def st(x):
        return print(x)


class Solution:
    def __init__(self):
        return

    @staticmethod
    def main(ac=FastIO()):
        # 模板：经典特定中位数的连续子数组个数，使用容斥原理加前缀和有序列表二分
        n, m = ac.read_ints()
        nums = ac.read_list_ints()

        def check(x):
            cur = res = s = 0
            dct = [0]*(2*n+1)
            dct[cur] = 1
            for num in nums:
                if num >= x:
                    s += dct[cur]
                    cur += 1
                else:
                    cur -= 1
                    s -= dct[cur]
                res += s
                dct[cur] += 1
            return res
        ac.st(check(m) - check(m + 1))
        return


Solution().main()

