const int MAXN=200005;
int n,m,k,tot,g[MAXN],a,b,dis[MAXN],ans;
char s[MAXN];
vector<string>v;
struct edge
{
    int to,next,ki;
}e[MAXN<<1];
void add_edge(int from,int to,int ki)
{
    e[++tot].to=to;
    e[tot].ki=ki;
    e[tot].next=g[from];
    g[from]=tot;
    return;
}
void dfs(int x)
{
    if(x==n+1)
    {
        ++ans;
        v.push_back(string(s+1));
        return;
    }
    for(int i=g[x];i;i=e[i].next)
    {
        if(dis[e[i].to]+1==dis[x])
        {
            s[e[i].ki]='1';
            dfs(x+1);
            s[e[i].ki]='0';
            if(ans==k)break;
        }
    }
    return;
}
queue<int>q;
