{
    scanf("%d %d %d",&n,&m,&k);
    for(int i=1;i<=m;++i)
    {
        scanf("%d %d",&a,&b);
        add_edge(a,b,i);
        add_edge(b,a,i);
    }
    memset(dis,-1,sizeof(dis));
    dis[1]=0;
    q.push(1);
    while(!q.empty())
    {
        int x=q.front();
        q.pop();
        for(int i=g[x];i;i=e[i].next)
        {
            if(dis[e[i].to]==-1)
            {
                dis[e[i].to]=dis[x]+1;
