  for l1, l2 in links:
    # print(ls)
    # print(ls.get(l1, []))
    ls.setdefault(l1, []).append(l2)
    ls.setdefault(l2, []).append(l1)

  # print(ls)
  g = {}
  ig = {}
  leaves = []
  todo = deque([(-1, 1)])
  while len(todo) > 0:
    pp, p = todo.popleft()
    ll = ls[p]
    c = []
    for l in ll:
      if l == pp:
        continue
      c.append(l)
      ig[l] = p
      todo.append((p, l))
    if len(c) == 0:
      leaves.append(p)
    else:
      g[p] = c
    # print(p)
    # print(ll)
    # print(g)
    # print(ig)
  return g, ig, leaves

def combine(childs):
  if len(childs) == 0:
    return [1], 0

  mlen = max([len(a) for a in childs])
  res = [0 for a in range(mlen)]
  for c in childs:
    for a in range(len(c)):
      res[mlen-a-1] += c[-1-a]

  res.append(1)
  lm = 1
  li = 0
  for a in range(mlen-1, -1, -1):
    if res[a] > lm:
      lm = res[a]
      li = mlen - a
  return res, li

def calcgraph(num, links):
  g, ig, leaves = makegraph(links)
  # print(g, ig, leaves)

  ans = list([0 for a in range(num)])

  child = {}
  cscratch = {}

  todo = deque(leaves)

  while len(todo) > 0:
    n = todo.popleft()
    res, dom = combine(cscratch.get(n, []))
    ans[n-1] = dom
    if n > 1:
      p = ig[n]
      new = cscratch.setdefault(p, [])
      new.append(res)
      if len(new) == len(g[p]):
        todo.append(p)


  return '\n'.join([str(a) for a in ans])

