inline bool chk() {
    queue <int> q;
    for (int i = 1; i <= n; i++) {
        vis[i] = 0;
        d[i] = deg[i];
        if (!d[i]) q.push(i);
    }
    for (; !q.empty(); ) {
        int x = q.front(); 
        q.pop();
        vis[x] = 1;
        for (int i = head[x]; i; i = e[i].nxt) {
            int y = e[i].to;
            --d[y];
            if (!d[y]) q.push(y);
        }
    }
    for (int i = 1; i <= n; i++)
        if (!vis[i])
            return 0;
    return 1;
}

