int n;
ll ans;
const int N = 212345;
vector<int> adj[N];
ll V[N];

struct st {
	ll qtp;
	ll qtn;
	ll sump;
	ll sumn;

	void init(ll v) {
		qtp = 1;
		qtn = 0;
		sump = v;
		sumn = 0;
		ans += v;
	}
	void join(ll v, st &o) {
		ans = mod(ans + qtp * (-o.sump - o.sumn) + (o.qtp + o.qtn) * sump);
		ans = mod(ans + qtn * (o.sump + o.sumn) + (o.qtp + o.qtn) * (-sumn));
		ans = mod(ans + o.qtp * (-sump - sumn) + (qtp + qtn) * o.sump);
		ans = mod(ans + o.qtn * (sump + sumn) + (qtp + qtn) * (-o.sumn));
		ans = mod(ans + modn);
		qtp += o.qtn;
		qtn += o.qtp;
		sump = mod(sump + (-o.sumn) + o.qtn * v);
		sump = mod(sump + modn);
		sumn = mod(sumn + (-o.sump) + o.qtp * v);
		sumn = mod(sumn + modn);
	}
} s[N];


void solve(int u, int p) {
	s[u].init(V[u]);
	for(int v : adj[u]) {
		if(v == p) continue;
		solve(v, u);
		s[u].join(V[u], s[v]);
	}
}

