int main() {
	n=rd(),q=rd();
	f(i,1,n) a[i]=rd()+a[i-1];
	ll sum=0,l=1,r=n,last=0;
	f(i,1,q) {
		ll k=rd();

		if(k >= a[n]-sum) {
			out(n);
			sum=0,l=1,r=n,last=0;
			continue;
		}
		while(l<r) {
			int mid=(l+r)>>1;
			if(a[mid]-sum >= k) r=mid;
			else l=mid+1;
		}
		sum+=k;r=n;
		last=a[l]-sum;
		out(last==0?n-l:n-l+1);
		if(!last) l++;
	}
	return 0;
}

