def solve(A):
    N = len(A)

    def query(prev, diff):
        ans = 0
        for i in range(1, N):
            for x in range(A[i] - 1,  A[i]+2):
                if prev + diff == x:
                    prev = x
                    ans += prev != A[i]
                    break
            else:
                return math.inf
        return ans


