    for fst in range(A[0] - 1, A[0] + 2):
        for snd in range(A[1] - 1, A[1] + 2):
            changes = +(fst != A[0])
            diff = snd - fst
            ans = min(ans, changes + query(fst, diff))

    return ans if ans < math.inf else -1

