def factor(x):
    if factor_dict[x] is not None:
        return factor_dict[x]
    for p in primes:
        if p*p > x:
            break
        if x % p==0:
            x2 = x
            c = 0
            while x2 % p==0:
                x2 = x2//p
                c+=1
            L = factor(x2)
