def process(Q):
    q = len(Q)
    curr = [[{}, {}] for j in range(17)]
    present = [0 for i in range(10**5+1)]
    answer = []
    for i in range(q):
        task = Q[i]
        if task[0]==1:
            u = task[1]
            if present[u]==0:
                b = bin(u)[2:].zfill(17)
                for ui in factor(u):
                    for I in range(17):
                        if b[I]=='0':
                            if ui not in curr[I][0]:
                                curr[I][0][ui] = float('inf')
                            curr[I][0][ui] = min(curr[I][0][ui], u)
                        else:
                            if ui not in curr[I][1]:
                                curr[I][1][ui] = float('inf')
                            curr[I][1][ui] = min(curr[I][1][ui], u)
                present[u] = 1
        else:
            x, k, s = task[1], task[2], task[3]
            if x % k != 0:
                answer.append(-1)
            my_answer = -1
            x2 = bin(x)[2:].zfill(17)
            for I in range(17):
                if x2[I]=='0' and k in curr[I][1]:
                    if curr[I][1][k] <= s-x:
                        my_answer  = curr[I][1][k]
                        break
                elif x2[I]=='1' and k in curr[I][0]:
                    if curr[I][0][k] <= s-x:
                        my_answer = curr[I][0][k]
                        break
                elif k in curr[I][0] and curr[I][0][k] <= s-x:
                    my_answer = curr[I][0][k]
                elif k in curr[I][1] and curr[I][1][k] <= s-x:
                    my_answer = curr[I][1][k]
            answer.append(my_answer)
    return answer








