const int maxn = 2e6 + 7;

int n, timestamp;
int anc[maxn], o[maxn];
int p[maxn], L[maxn], R[maxn];
int nxt[maxn], v[maxn], head[maxn];
int r[maxn];
bool vis[maxn];

void update(int x, int value) {
	if (!x) return ;
	while (x <= n) {
		r[x] += value;
		x += x & -x;
	}
}

int query(int x) {
	int rt = 0;
	if (x == 0) return 0;
	while (x) {
		rt += r[x];
		x -= x & -x;
	}
	return rt;
}

void insert(int a, int b) {
	static int N = 0;
	N++;
	nxt[N] = head[a];
	head[a] = N;
	v[N] = b;
}

int main() {
//	freopen("input.txt", "r", stdin);
	int k;
	scanf("%d%d", &n, &k);
	for (int i = 1; i < n; i++) {
		int u, v;
		scanf("%d%d", &u, &v);
		insert(u, v);
		insert(v, u);
	}

	for (int i = 1; i <= n; i++) p[i] = head[i];

	int h = 0;
	o[h] = n;
	L[n] = ++timestamp;
	while (h >= 0) {
		int u = o[h];
		if (!p[u]) {
			h--;
			R[u] = timestamp;
			continue;
		}
		int tar = v[ p[u] ]; p[u] = nxt[ p[u] ];
		if (tar == anc[u]) continue;
		anc[tar] = u;
		o[++h] = tar;
		L[tar] = ++timestamp;
	}

	for (int i = 1; i < n; i++) {
		update(R[i] + 1, -1);
		update(L[i], 1);
	}

	vis[n] = true;	
	// calced[n] = true;

	int rest = n - k - 1;
	for (int i = n - 1; i >= 1; i--) {
		if (vis[i]) continue;
		if (query(L[i]) > rest) continue;

		int u = i;
		while (!vis[u]) {
			vis[u] = true;
			rest--;
			update(R[u] + 1, 1);
			update(L[u], -1);
			u = anc[u];
		}
	}
	for (int i = 1; i <= n; i++) 
		if (!vis[i]) printf("%d ", i);
	puts("");
	return 0;
}

