bool solve(long long n, long long k){
	if (solved[n][k])
		return dp[n][k];
	bool solution = false;
	if (k == 1){
		long long sum = 0;
		for (long long i = 0; i < n; i++){
			sum += values[i];
		}
		if ((sum & desiredNumber) == desiredNumber){
			solution = true;
		}
	} else {//k > 1
		long long sum = 0;
		for (long long i = 0; ((i < n - k + 1) && (!solution)); i++){
			sum += values[n - 1 - i];
			if ((sum & desiredNumber) == desiredNumber){
				solution = solve(n - i - 1, k - 1);
			}
		}
	}
	solved[n][k] = true;
	dp[n][k] = solution;
	return dp[n][k];
}

