const int N = int(1e4) + 10;
using bs = bitset<N>;

struct segtree
{
    vvi who;
    int tsz;

    segtree (int n)
    {
        tsz = 1;
        while (tsz < n)
            tsz *= 2;

        who.resize(2 * tsz);
    }

    void add (int l, int r, int x)
    {
        for (l += tsz, r += tsz; l < r; l >>= 1, r >>= 1)
        {
            if (l & 1)
                who[l++].pb(x);
            if (r & 1)
                who[--r].pb(x);
        }
    }

    bs get (int v)
    {
        bs ans;
        ans[0] = 1;
        if (v < tsz)
            ans = get(2 * v) | get(2 * v + 1);
        for (int x : who[v])
            ans |= ans << x;
        return ans;
    }

    bs get ()
    {
        return get(1);
    }
};

