struct IO_Tp
{
	bool is_digit(const char ch)
	{
		return '0' <= ch && ch <= '9';
	}

	IO_Tp& operator>>(int& res)
	{
		res = 0;
		static char ch;
		while (ch = getchar(), !is_digit(ch))
			;
		do
			(res *= 10) += ch & 15;
		while (ch = getchar(), is_digit(ch));
		return *this;
	}

	char getop()
	{
		static char ch;
		while (ch = getchar(), !is_digit(ch))
			;
		return ch & 15;
	}
} IO;

const int Max_N(100005), Mod(998244353);

int N, M, K, S;
std::vector<int> s[105];
int dist[105][Max_N];
int ecnt(1), first[Max_N * 2], Next[Max_N * 2], To[Max_N * 2]; 

void bfs(const int k)
{
	for (int i(1); i <= N; ++i)
		dist[k][i] = 1 << 30;
	static int queue[Max_N];
	int *cur1(queue), *cur2(queue);
	for (int i(0); i != s[k].size(); ++i)
		dist[k][*++cur2 = s[k][i]] = 0;
	while (cur1 != cur2)
	{
		int v(*++cur1);
		for (int e(first[v]); e; e = Next[e])
			if (dist[k][To[e]] == (1 << 30))
				dist[k][To[e]] = dist[k][v] + 1, *++cur2 = To[e];
	}
}

int main(int argc, char **argv)
{
	IO >> N >> M >> K >> S;
	for (int i(1), a; i <= N; ++i)
		IO >> a, s[a].push_back(i);
	for (int i(0), v, w; i != M; ++i)
	{
		IO >> v >> w;
		Next[ecnt] = first[v], To[ecnt] = w, first[v] = ecnt++;
		Next[ecnt] = first[w], To[ecnt] = v, first[w] = ecnt++;
	}

	for (int i(1); i <= K; ++i)
		bfs(i);

	for (int i(1); i <= N; ++i)
	{
		static int tmp[Max_N];
		for (int k(1); k <= K; ++k)
			tmp[k] = dist[k][i];
		std::nth_element(tmp + 1, tmp + S, tmp + 1 + K);
		int Ans(0);
		for (int k(1); k <= S; ++k)
			Ans += tmp[k];
		printf("%d ", Ans);
	}

	return 0;
}

