using namespace std;

int main()
{
    ios_base::sync_with_stdio(false);

    int a, n, m;

    cin >> a >> n >> m;

    vector<array<int, 2>> segs(n);
    for(int i = 0; i < n; ++i)
        cin >> segs[i][0] >> segs[i][1];

    sort(segs.begin(), segs.end());

    vector<int> best(a + 1);
    for(int i = 0; i < a + 1; ++i)
    {
        best[i] = i;
    }
    vector<int> dp(a + 1, -1);
    for(int i = 0; i <= segs[0][0]; ++i)
    {
        best[i] = 0;
        dp[i] = 0;
    }
    for(int i = 1; i < n; ++i)
    {
        for(int j = segs[i - 1][1]; j <= segs[i][0]; ++j)
        {
            best[j] = segs[i - 1][1];
        }
    }
    for(int i = segs.back()[1]; i < a + 1; ++i)
    {
        best[i] = segs.back()[1];
    }

    vector<array<int, 2>> umbrelas(m);
    for(int i = 0; i < m; ++i)
    {
        cin >> umbrelas[i][0] >> umbrelas[i][1];
    }

    sort(umbrelas.begin(), umbrelas.end());
    for(const array<int, 2>& u : umbrelas)
    {
        if(dp[u[0]] != -1)
        {
            for(int i = u[0] + 1; i < a + 1; ++i)
            {
                if(u[0] < best[i])
                {
                    int neu = dp[u[0]] + u[1] * (best[i] - u[0]);

                    if(dp[i] == -1 || neu < dp[i])
                    {
                        dp[i] = neu;
                    }
                }
            }
        }
    }

    cout << dp[a];

    return 0;
}

