using namespace std;
const int N=2e5+5,E=N<<1;
int La[N],To[E],Ne[E],TOT;
int siz[N],dep[N],cnt[N];
int tmp[N],val[N],tot;
int NOW[N],ALL,CNT[N];
long long ans[N];
bool vis[N];
void AE(int x,int y) {
	To[++TOT]=y;
	Ne[TOT]=La[x];
	La[x]=TOT;
}
int MIN,Root,S;
void dfs(int u,int fa,int cur) {
	int i,v,MAX=0;
	dep[u]=__gcd(cur,val[u]);
	if(!cnt[dep[u]]) tmp[++tot]=dep[u];
	cnt[dep[u]]++;
	for(i=La[u];i;i=Ne[i]) {
		v=To[i];
		if(vis[v]||v==fa) continue;
		dfs(v,u,dep[u]);
	}
}
void clear() {
	while(ALL) CNT[NOW[ALL--]]=0;
}
void DFS(int u,int fa) {
	int i,v,MAX=0;
	siz[u]=1;
	for(i=La[u];i;i=Ne[i]) {
		v=To[i];
		if(vis[v]||v==fa) continue;
		DFS(v,u);siz[u]+=siz[v];
		if(siz[v]>MAX) MAX=siz[v];
	}
	if(MAX<S-siz[u]) MAX=S-siz[u];
	if(MIN>MAX) MIN=MAX,Root=u;
}
int FindRoot(int u,int s) {
	S=s;MIN=1e9;DFS(u,u);return Root;
}
void update() {
	int i,j,k;
	for(i=1;i<=tot;i++) {
		for(j=1;j<=ALL;j++) {
			ans[__gcd(NOW[j],tmp[i])]+=1LL*cnt[tmp[i]]*CNT[NOW[j]];
		}
	}
	for(i=1;i<=tot;i++) {
		if(!CNT[tmp[i]]) NOW[++ALL]=tmp[i];
		CNT[tmp[i]]+=cnt[tmp[i]];
		cnt[tmp[i]]=0;
	}
	tot=0;
}
void DC(int rt,int s) {
	int i,j,k,v;
	vis[rt]=1;
	ans[val[rt]]++;
	if(s==1) return;
	CNT[NOW[++ALL]=val[rt]]=1;
	for(i=La[rt];i;i=Ne[i]) {
		if(vis[v=To[i]]) continue;
		dfs(v,v,val[rt]);
		update();
	}
	clear();
	for(i=La[rt];i;i=Ne[i]) {
		if(vis[v=To[i]]) continue;
		if(siz[v]>siz[rt]) {
			siz[v]=s-siz[rt];
		}
		k=siz[v];v=FindRoot(v,k);DC(v,k);
	}
}
int n;
int main() {
	int i,j,k,x,y;
	scanf("%d",&n);
	for(i=1;i<=n;i++) scanf("%d",&val[i]);
	for(i=1;i<n;i++) {
		scanf("%d%d",&x,&y);
		AE(x,y);AE(y,x);
	}
	DC(FindRoot(1,n),n);
	for(i=1;i<N;i++) {
		if(ans[i]) {
			cout<<i<<' '<<ans[i]<<endl;
		}
	}
}

