inline void fft(cp *x,int n,int flag)  
{  
    F(i,0,n-1) if (rev[i]>i) swap(x[i],x[rev[i]]);  
    for(int m=2;m<=n;m<<=1)  
    {  
        cp wn=(cp){cos(2.0*PI/m*flag),sin(2.0*PI/m*flag)};  
        for(int i=0;i<n;i+=m)  
        {  
            cp w=(cp){1.0,0};  
            int mid=m>>1;  
            F(j,0,mid-1)  
            {  
                cp u=x[i+j],v=x[i+j+mid]*w;  
                x[i+j]=u+v;x[i+j+mid]=u-v;  
                w=w*wn;  
            }  
        }  
    }  
    if(flag==-1) F(i,0,n-1) x[i].x/=n;  
}  
