const int maxn = 5000 + 100 ;

int n , m , s , ans ;

struct Edge {
    int u , v ;
    Edge *next ;
} E[maxn] , *header[maxn] ;

stack <int> gstack ;

bool instack[maxn] ;

int DFN[maxn] , LOW[maxn] ;
int belg[maxn] , num[maxn] ;

int tot , tag , scc ;
void add_edge(int u , int v){
    E[++tot].u = u ; E[tot].v = v ;  E[tot].next = header[u] ; header[u] = &E[tot] ;
}

int indegree[maxn] ;

void tarjan(int u){ 
    DFN[u] = LOW[u] = ++tag ;
    gstack.push(u) ;
    instack[u] = true ;
    for(Edge *e = header[u] ; e ; e = e->next){
        if(!DFN[e->v]){
            tarjan(e->v) ;
            LOW[u] = min(LOW[u] , LOW[e->v]) ;
        } else if(instack[e->v]){
            LOW[u] = min(LOW[u] , DFN[e->v]) ;
        }
    }
    if(LOW[u] == DFN[u]){
        instack[u] = false ;
        belg[u] = ++scc ;
        while(gstack.top() != u){
            int v = gstack.top() ; gstack.pop() ;
            belg[v] = scc ; instack[v] = false ;
        }
        gstack.pop() ;
    }
}

