    for(int i = 1 ; i <= m ; ++i){
        int u = E[i].u ; 
        int v = E[i].v ;
        if(belg[u] != belg[v]){
            ++indegree[belg[v]] ;
        }
    }

    for(int i = 1 ; i <= scc ; ++i){
