    while (t--) {
        int n;
        cin >> n;
        vector<int> template_array(n);
        for (int i = 0; i < n; ++i) {
            cin >> template_array[i];
        }

        int m;
        cin >> m;
        vector<string> strings(m);
        for (int i = 0; i < m; ++i) {
            cin >> strings[i];
        }

        for (const string& s : strings) {
            if (check_template_match(template_array, s)) {
                cout << "YES" << endl;
            } else {
                cout << "NO" << endl;
            }
        }
    }

    return 0;
}

