ll dfs(vvl &a, vvl &visited, ll i, ll j, ll n, ll m){
    if(i < 0 || j < 0 || i >= n || j >= m || visited[i][j] || a[i][j] == 0)
        return 0;

    visited[i][j] = 1;
    ll ans = a[i][j];
    ans += dfs(a, visited, i+1, j, n, m);
    ans += dfs(a, visited, i-1, j, n, m);
    ans += dfs(a, visited, i, j+1, n, m);
    ans += dfs(a, visited, i, j-1, n, m);

    return ans;
}

void solve()
{
