    ll ans = 0;
    for(int i = 0; i < n; i++){
        for(int j = 0; j < m; j++){
            if(!visited[i][j] && a[i][j] != 0){
                ans = max(ans, dfs(a, visited, i, j, n, m));
            }
        }
    }

    cout<<ans<<endl;
}

