typedef long long ll;

ll bf(ll x, vector<ll> &a)

{

    ll l = 0, r = a.size() - 1, m;

    while (l != r)

    {

        m = (l + r + 1) / 2;

        if (a[m] > x)

            r = m - 1;

        else

            l = m;

    }

    if (a[l] != x)

        return 0;

    ll b = l;

    l = 0, r = a.size() - 1;

    while (l != r)

    {

        m = (l + r) / 2;

        if (a[m] >= x)

            r = m;

        else

            l = m + 1;

    }

    return b - l + 1;

}

void solve()

{

    ll n, ctr = 0;

    long double m = 0;

    cin >> n;

    vector<ll> a(n);

    for (ll i = 0; i < n; ++i)

        cin >> a[i], m += a[i];

    m /= n;

    m *= 2;

    sort(a.begin(), a.end());

    for (ll i = 0; i < n; ++i)

    {

        if (m - a[i] != round(m - a[i]))

            continue;

        ctr += bf(m - a[i], a);

        if(a[i]*2==m)

            --ctr;

    }

    cout << ctr / 2 << '\n';

}

