struct edge{
	int f, t, next;
} e[MAXM];

int head[MAXN], etot = 0;

void add_edge(int u, int v){
	e[++etot].f = u;
	e[etot].t = v;
	e[etot].next = head[u];
	head[u] = etot;
}

int dp[MAXN];

void dfs(int cur, int fa = 0){
	dp[cur] = 0;
	int cnt = 0;
	for(int i = head[cur]; i; i = e[i].next){
		int to = e[i].t;
		if(to == fa) continue;
		dfs(to, cur);
		dp[cur] += dp[to];
		++cnt;
	}
	if(!cnt) dp[cur] = 1;
	// cout << cur space dp[cur] << "\n";
}

void clear(){
    etot = 0;
    for(int i = 1; i <= n; ++i) head[i] = dp[i] = 0;
}

