struct tree {

	vector <lol> t;

	void init(lol n) {

		t.resize(n * 4);

	}

	void build(vector <lol>& a, int v, int tl, int tr) {

		if (tl == tr) {

			t[v] = a[tl];

			return;

		}

		int tm = (tl + tr) / 2;

		build(a, v * 2, tl, tm);

		build(a, v * 2 + 1, tm + 1, tr);

		t[v] = t[v * 2] + t[v * 2 + 1];

	}

	void up(int v, int tl, int tr, int pos, lol val) {

		if (tl == tr) {

			t[v] = val;

			return;

		}

		int tm = (tl + tr) / 2;

		if (pos <= tm) up(v * 2, tl, tm, pos, val);

		else up(v * 2 + 1, tm + 1, tr, pos, val);

		t[v] = t[v * 2] + t[v * 2 + 1];

	}

	int ans() {

		return t[1];

	}



};



