ll a[MAXN];

ll simulate(ll k) {
    ll ans = 0, expired = 0;
    rep(i, 0, N) {
        if (a[i] >= expired) ans += k;
        else
            ans += a[i] + k - expired;
        expired = a[i] + k;
    }
    return ans;
}

ll solve() {
    input(N, H);
    rep(i, 0, N) input(a[i]);
    ll l = 0, r = 1e18 + 1, res = 1e18;
    while (l <= r) {
        ll m = (l + r) >> 1;
        ll cur = simulate(m);
        if (cur >= H) res = m, r = m - 1;
        else
            l = m + 1;
    }
    return res;
}

