bool is_possible(int n, const vector<int> &a, int k) {
    int count = 0;
    int i = 0;
    while (i < n - 1) {
        if (a[i + 1] - a[i] <= k) {
            count++;
            i += 2;
        }
        else {
            i += 1;
        }
    }
    int required = n / 2;
    return count >= required;
}

