template <typename T>

struct Fenwick {

    std::vector<T> ar;

    Fenwick(int64_t n) : ar(n) {}

    Fenwick(vector<T> &br)

    {

        ar.resize(br.size(), 0);

        for (int64_t i = 0; i < br.size(); ++i)

            add(i, br[i]);

    }

    void add(int64_t i, T val) {

        while (i < ar.size())

        {

            ar[i] += val;

            i |= (i + 1);

        }

    }

    T prefSum(int64_t i) {

        T ans = 0;

        while (i >= 0)

        {

            ans += ar[i];

            i &= (i + 1); --i;

        }

        return ans;

    }

    T rangeSum(int64_t l, int64_t r) {

        return prefSum(r) - prefSum(l - 1);

    }

};



void solve()

{

    int n, q; cin >> n >> q;

    Fenwick<int> row(n), col(n);

    vector<int> row_v(n), col_v(n);

    for (int i = 0; i < q; ++i)

    {

        int c; cin >> c;

        if (c == 1)

        {

            int x, y; cin >> x >> y; --x; --y;

            ++row_v[x]; ++col_v[y];

            if (row_v[x] == 1)

                row.add(x, 1);

            if (col_v[y] == 1)

                col.add(y, 1);

        }

        else if (c == 2)

        {

            int x, y; cin >> x >> y; --x; --y;

            --row_v[x]; --col_v[y];

            if (!row_v[x])

                row.add(x, -1);

            if (!col_v[y])

                col.add(y, -1);

        }

        else if (c == 3)

        {

            bool cover = false;

            int x1, y1, x2, y2; cin >> x1 >> y1 >> x2 >> y2; --x1; --x2; --y1; --y2;

            int rw = row.rangeSum(x1, x2), cl = col.rangeSum(y1, y2);

            if (rw == x2 - x1 + 1 || cl == y2 - y1 + 1)

            {

                cover = true;

            }

            cout << (cover ? "Yes" : "No") << '\n';

        }

    }

}



