class PrefixSum{
    private: 
        int n;
        vector<int> prefix;
    public:
    PrefixSum(const vector<int>& nums){
        int n = nums.size();
        vector<int> prefix(n + 1, 0);
        for (int i = 1; i < n; ++i) {
            prefix[i] = prefix[i - 1] + nums[i - 1];
        }   
    }

    int getSum(int L, int R){
        return prefix[R] - prefix[L - 1];
    }
};
