void run_case() {
    int N, K; string T;
    cin >> N >> K >> T;

    vector<pair<int, int>> gaps;
    for (int i = 0; i < N - 1;) {
        if (T[i] == 'W' && T[i + 1] == 'L') {
            int end = i;
            while (end + 1 < N && T[end + 1] != 'W')
                end++;

            if (end + 1 == N) {
                break;
            }

            gaps.push_back({i + 1, end});
            i = end;
        } else {
            i++;
        }
    }

    sort(gaps.begin(), gaps.end(), [](pair<int, int> a, pair<int, int> b) {
        return a.second - a.first < b.second - b.first;
    });

    for (auto g : gaps) {
        for (int i = g.first; i <= g.second && K > 0; i++) {
            T[i] = 'W';
            K--;
        }
    }

    for (int i = 0; i < N; i++) {
        if (T[i] == 'W') {
            for (int j = i + 1; j < N && K > 0; j++) {
                if (T[j] != 'W') {
                    T[j] = 'W';
                    K--;
                }
            }
            for (int j = i - 1; j >= 0 && K > 0; j--) {
                if (T[j] != 'W') {
                    T[j] = 'W';
                    K--;
                }
            }
            break;
        }
    }

    for (int i = 0; i < N && K > 0; i++)
        if (T[i] != 'W') {
            T[i] = 'W';
            K--;
        }

    int answer = 0;
    for (int i = 0; i < N; i++)
        if (T[i] == 'W') {
            answer++;
            if (i > 0 && T[i - 1] == 'W')
                answer++;
        }

    cout << answer;
}

