	number(int _son = 1, int _mother = 1) {
		son = _son;
		mother = _mother;
		if(mother != 0) {
			if(son != 0) {
				sign = (son/abs(son))*(mother/abs(mother));
			} else {
				sign = 0;
			}
			son = abs(son);
			mother = abs(mother);
			int g = gcd(son, mother);
			if(g != 0) {
				son /= g;
