int solve(vector<char> &v, int l, int r, char c) {

    if (r-l == 1) return v[l] == c ? 0 : 1;

    int countLeft = 0, countRight = 0;

    int m = (l+r) >> 1;

    for (int i = l; i < m; i++) {

        countLeft += (v[i] != c);

    }

    for (int i = m; i < r; i++) {

        countRight += (v[i] != c);

    }

    return min(countLeft + solve(v, m, r, c+1), countRight + solve(v, l, m, c+1));

}



