    ((p1 == p2) ? (p2 = buf + fread(p1 = buf, 1, 1 << MaxSize, stdin), p1 == p2 ? EOF : *p1++) : *p1++)

template <class T>
inline void in(T &x) {
    x = 0;
    register bool f = 0;
    register char c = GetChar();

    while (c < 47 || c > 58) {
        f |= (c == '-'), c = GetChar();
    }

    while (c > 46 && c < 59) {
        x = (x << 3) + (x << 1) + (c & 15), c = GetChar();
    }

    x = f ? (~x + 1) : x;
}

