    for (register LL i = 1; i <= n; ++i)
    	in(a[i]), maxi = max(maxi, a[i]);
    for (register LL i = 1; i <= n; ++i)
        if (a[i] == maxi)
            ++cnt;
    if (cnt >= 2) {
        printf("%lld\n", res[n]);
        return ;
    }
    cnt = 0;
    for (register LL i = 1; i <= n; ++i)
        if (a[i] == maxi - 1)
            ++cnt;
    if (cnt == 0) {
        puts("0");
        return ;
    }
    printf("%lld\n", ((res[n] - res[n] * Pow(cnt + 1, Mod - 2) % Mod) + Mod) % Mod);	
	return ;
}

signed main() {
    in(T);
    res[0] = 1;
    for (LL i = 1; i <= MaxN; ++i)
        res[i] = res[i - 1] * i % Mod;
    while (T--) {
		Solve();
    }
    return 0;
}

