LL n, m, mx, res, x;

int qmi(int a, int k, int p)  // 求a^k mod p
{
    int res = 1 % p;
    while (k)
    {
        if (k & 1) res = (LL)res * a % p;
        a = (LL)a * a % p;
        k >>= 1;
    }
    return res;
}

void solve()
{
    mx = 0;
    n = read(), m = read();

    res = 0;
    LL mul = qmi(2, n - 1, mod);

    while (m -- ) read(), read(), x = read(), mx |= x;

    for (int i = 0; i <= 31; i ++ )
        if (mx >> i & 1)
        {
            res += (LL)mul * (1LL << i);
            if(res >= mod) res %= mod;
        }

    cout << res << '\n';
}

