struct segtree {
  vector<int> t;
  int n = 1;
  segtree(int s) {
    while(n < s) n *= 2;
    t.resize(n * 2);
  }
  void update(int i, int x) {
    for(t[i += n] = x; i /= 2;) {
      t[i] = t[i * 2] + t[i * 2 + 1];
    }
  }
  int query(int l, int r) {
    int res = 0;
    for(l += n, r += n; l < r; l /= 2, r /= 2) {
      if(l & 1) res += t[l++];
      if(r & 1) res += t[--r];
    }
    return res;
  }
};

