const int MOD = 1e9 + 7;

int bin_pow(int a, int n) {
	int res = 1;
	for (int s = a; n; s = (s * s) % MOD, n >>= 1ll) {
		if (n & 1ll)
			res = (res * s) % MOD;
	}
	return res;
}

int back_mod(int a) {
	return bin_pow(a, MOD - 2);
}

int solve(int n, int k, vector<int> &arr) {
	vector<int> cnt(n + 1, 0);
	for (int val: arr)
		++cnt[val];
//	cout << "cnt: "; print(cnt);
	vector<int> fact(n + 1, 1);
	for (int i = 1; i <= n; ++i)
		fact[i] = fact[i - 1] * i % MOD;
	for (int i = n; i >= 0; --i) {
		if (cnt[i] <= k) {
			k -= cnt[i];
			continue;
		}
		int val = cnt[i];
	//	debug("val", val);
		int ans = fact[val] * back_mod(fact[k]) % MOD * back_mod(fact[val - k]) % MOD;
		return ans;
	}
	return 1;
}

