			ll minn=inf;
			for(register int i=head[u];i;i=nxt[i]){
				int v=ver[i];
				if(v!=f[u]) minn = min(sum[v],minn);
			}
			if(minn==inf) a[u]=0;     //没有儿子 
			else{
				a[u] = minn-sum[f[u]];  //附上最大可能值 
				for(register int i=head[u];i;i=nxt[i]){
					int v=ver[i];
					if(v==f[u]) continue;
					a[v] = sum[v]-minn;
					q.push(v);
				} 
			}
		}
	}
}
