using namespace std;

bool checkOn(int N, int K) {

	return N & (1 << K);

}

void turnOn(int &N, int K)  {

	N |= (1 << K);

}

void turnOff(int &N, int K) {

	N &= ~(1 << K);

}

bool checkOff(int N, int K) {

	return !(N & (1 << K));

}

int32_t main() {

	ios_base::sync_with_stdio(false); cin.tie(nullptr);

	int N, M; cin >> N >> M;

