	vector<int> B(M); for (auto &b : B) cin >> b;

	vector<bool> found(512, false);

	for (int i = 0; i < 512; ++i) {

		for (int j = 0; j < M; ++j) {

			bool good = true;

			for (int k = 0; k < 10; ++k) {

				if (checkOff(i, k) && checkOn(B[j], k)) good = false;

			}

			if (good) found[i] = true;

		}

	}

	for (int i = 0; i < 512; ++i) {

		int cnt = 0;

		for (int j = 0; j < N; ++j) {

			int mask = 512-1;

			for (int k = 0; k < 10; ++k) {

				if (checkOff(i, k) && checkOn(A[j], k)) turnOff(mask, k);

			}

			if (found[mask]) ++cnt;

		}

		if (cnt == N) {

			cout << i << endl;

			return 0;

		}

	}

	return 0;

}

