typedef long long ll;
const int S=5;
ll factor[128],tot;
ll gcd(ll a,ll b){return b==0?a:gcd(b,a%b);}
ll qmul(ll a,ll b,ll c){
	ll ans=0;
	a%=c,b%=c;
	while(b){
		if(b&1){
			ans+=a;
			if(ans>c)ans-=c;
		}
		a<<=1;;
		if(a>c)a-=c;
		b>>=1;
	}
	return ans;
}
ll qpow(ll a,ll b,ll c){
	ll ans=1;
	a%=c;
	while(b){
		if(b&1)ans=qmul(ans,a,c);
		a=qmul(a,a,c);
		b>>=1;
	}
	return ans;
}
bool check(ll a,ll n,ll x,ll t){
	ll ans=qpow(a,x,n);
	ll last=ans;
	for(int i=1;i<=t;++i){
		ans=qmul(ans,ans,n);
		if(ans==1&&last!=i&&last!=n-1)return true;
		last=ans;
	}
	return ans!=1;
}
bool Miller_Rabin(ll n){
	if(n<2)return false;
	if(n==2||n==3||n==5||n==7)return true;
	if((n&1)==0)return false;
	ll x=n-1,t=0;
	srand(time(NULL));
	for(int i=0;i<S;++i){
		ll a=rand()%(n-1)+1;
		if(check(a,n,x,t))return false;
	}
	return true;
}
ll pollard_rho(ll x,ll c){
	srand(time(NULL));
	ll i=1,k=2,x0=rand()%(x-1)+1,y=x0;
	while(1){
		++i;
		x0=(qmul(x0,x0,x)+c)%x;
		ll d=gcd(abs(y-x0),x);
		if(d!=1&&d!=x)return d;
		if(y==x0)return x;
		if(i==k)y=x0,k<<=1;
	}
}
void findfactor(ll n,int k){
	if(n==1)return;
	if(Miller_Rabin(n)){
		factor[tot++]=n;return;
	}
	ll p=n;
	int c=k;
	while(p>=n)p=pollard_rho(p,c--);
	findfactor(p,k);
	findfactor(n/p,k);
}
