char str[100001];
int seg[1 << 18];
int makeSeg(int l, int r, int I = 1) {
    if (l == r) {
        return seg[I] = 1 << (str[l] - 'a');
    }
    int mid = l + r >> 1;
    int ll = makeSeg(l, mid, I << 1);
    int rr = makeSeg(mid + 1, r, I << 1 | 1);
    return seg[I] = ll | rr;
}
int find(int l, int r, int x, int y, int I = 1) {
    if (l > y || r < x) return 0;
    if (l >= x && r <= y) {
        return seg[I];
    }
    int mid = l + r >> 1;
    int ll = find(l, mid, x, y, I << 1);
    int rr = find(mid + 1, r, x, y, I << 1 | 1);
    return ll | rr;
}
void update(int l, int r, int x, int y, char diff, int I = 1) {
    if (l > y || r < x) return;
    if (l >= x && r <= y) {
        seg[I] = 1 << (diff - 'a');
        return;
    }
    int mid = l + r >> 1;
    update(l, mid, x, y, diff, I << 1);
    update(mid + 1, r, x, y, diff, I << 1 | 1);
    seg[I] = seg[I << 1] | seg[I << 1 | 1];
}
int popCount(int I) {
    return I ? popCount(I - (I & -I)) + 1 : 0;
}
int main() {
    int n, le;
    scanf("%s%d", str, &n);
    le = strlen(str);
    makeSeg(0, le - 1);
    for (int i = 0; i < n; ++i) {
        int p;
        scanf("%d", &p);
        if (p - 1) {
            int l, r;
            scanf("%d%d", &l, &r);
            printf("%d\n", popCount(find(0, le - 1, l - 1, r - 1)));
        } else {
            int pos;
            char c;
            scanf("%d %c", &pos, &c);
            update(0, le - 1, pos - 1, pos - 1, c);
        }
    }
    return 0;
}

