    string a, b;

    cin >> a >> b;



    union_find UF(ALPHA);

    for (int i = 0; i < n; ++i) {

        if (b[i] < a[i]) return -1;

        UF.unite(a[i] - MIN_CHAR, b[i] - MIN_CHAR);

    }



    return ALPHA - UF.count();

}



