const int LN = 200005;
int T;
int N, K, A[LN];
int DP[LN][64];
const int mod = 1e9 + 7;
int cnt(int x) {
	int ret = 0;
	while (x) {
		ret += x & 1;
		x /= 2;
	}
	return ret;
}
int main() {
	ios_base::sync_with_stdio(0); cin.tie(0);
	cin >> T;
	while (T--) {
		cin >> N >> K;
		for (int i = 1; i <= N; i++) {
			cin >> A[i];
		}
		for (int i = 1; i <= N; i++) {
			for (int j = 0; j < 64; j++)DP[i][j] = 0;
		}
		DP[0][63] = 1;
		for (int i = 1; i <= N; i++) {
			for (int j = 0; j < 64; j++) {
				DP[i][j & A[i]] = (DP[i][j & A[i]] + DP[i - 1][j]) % mod;
				DP[i][j] = (DP[i][j] + DP[i - 1][j]) % mod;
			}
		}
		int ans = 0;
		for (int i = 0; i < 64; i++) {
			if (cnt(i) == K) {
				ans = (ans + DP[N][i]) % mod;
			}
		}
		if (K == 6)ans--;
		cout << ans << '\n';
	}
}

