using namespace std;



long long N, M;

int a[100000];

long long dl, dr, k, dm;



long long query(long long i, long long x) {

    dl = 0; dr = 0;

    if (i != 0) {

        if (a[i] == a[i-1]) {

            if (x != a[i-1]) {

                dl++;

            }

        }

        else {

            if (x == a[i-1]) {

                dl--;

            }

        }

    }

    if (i != N - 1) {

        if (a[i] == a[i+1]) {

            if (x != a[i+1]){

                dr++;

            }

        }

        else {

            if (x == a[i+1]) {

                dr--;

            }

        }

    }



    a[i] = x;

    k = i + 1;



    dm = dl + dr;

    return (k - 1) *(dl) +(N - k) * (dr) + (k - 1) * (N - k) * (dm); 



}





int main() {

    ios_base::sync_with_stdio(0);

    cin.tie(0); cout.tie(0);



    cin >> N >> M;

