    long long ans = N + (N) * (N-1)/2;



    for (int i=0;i<N;++i) {

        cin >> x;

        ans += query(i,x);  

    }



    for (int m=0;m<M;++m) {

        cin >> i >> x;

        i--;

        ans += query(i,x);

        cout << ans << '\n';

