using namespace std;
int N;
int a[200005];
char ans[200005];
int getLong1(int i){
    int lst = a[i++];
    int cst = 0;
    while(i<N&&a[i]>lst){
        lst = a[i++];
        cst++;
    }
    return cst;
}
int getLong2(int i){
    int lst = a[i--];
    int cst = 0;
    while(i>=0&&a[i]>lst){
        lst = a[i--];
        cst++;
    }
    return cst;
}
int deal(void){
    int cst = 0;
    int l=0,r=N-1;
    int lst = 0;
    while(l<=r){
        if(a[l]<a[r]){
            if(lst<a[l]){
                lst = a[l++];
                ans[cst++] = 'L';
            }else if(lst<a[r]){
                lst = a[r--];
                ans[cst++] = 'R';
            }else{
                return cst;
            }
        }else if(a[l]>a[r]){
            if(lst<a[r]){
                lst = a[r--];
                ans[cst++] = 'R';
            }else if(lst<a[l]){
                lst = a[l++];
                ans[cst++] = 'L';
            }else{
                return cst;
            }
        }else{
            if(lst<a[l]){
                if(l==r||l+1==r){
                    lst = a[l++];
                    ans[cst++] = 'L';
                }else{
                    int ansL = getLong1(l);
                    int ansR = getLong2(r);
                    if(ansL<ansR){
                        lst = a[r--];
                        ans[cst++] = 'R';
                    }else{
                        lst = a[l++];
                        ans[cst++] = 'L';
                    }
                }
            }else{
                return cst;
            }

        }
    }
    return cst;
}

int main(void){
    cin>>N;
    for(int i=0;i<N;i++){
        scanf("%d",&a[i]);
    }
    cout<<deal()<<endl;
    cout<<ans<<endl;
    return 0;
}

