void solve() {
    int n, k;
    LL x;
    cin >> n >> k >> x;
    string s;
    cin >> s;
    vector<int> v;
    for (int i=0;i<n;++i) {
        if (s[i] == '*') {
            int cnt = 1;
            while (i + 1 < n && s[i+1] == s[i]) {
                ++cnt; ++i;
            }
            v.push_back(cnt);
        }
    }
    n = v.size();
    // dbg(v);
    // return;
    vector<LL> dp(n+1, -1);
    dp[n] = 1;
    for (int i=n-1;i>=0;--i) {
        if (dp[i+1] > (((LL)1e18) + 5) / (k * v[i] + 1)) {
            dp[i] = -1;
        } else {
            dp[i] = (dp[i+1] * (k * v[i] + 1));
        }
        if (dp[i] == -1) break;
    }
    // dbg(dp);
    // return;
    x--;
    vector<int> ret(n);
    for (int i=0;i<n;++i) {
        int lo = 0, hi = v[i] * k;
        while (lo < hi) {
            int mid = (lo + hi + 1) >> 1;
            if (dp[i+1] != -1 && dp[i+1] <= x / mid) {
                lo = mid;
            } else {
                hi = mid - 1;
            }
        }
        if (lo > 0) x -= lo * dp[i+1];
        ret[i] = lo;
    }
    // dbg(ret);
    // return;
    int j = 0, m = s.size();
    string answer = "";
    for (int i=0;i<m;++i) {
        if (s[i] == 'a') {
            answer += s[i];
        } else {
            while (i + 1 < m && s[i+1] == s[i]) {
                ++i;
            }
            answer += string(ret[j], 'b');
            ++j; 
        }
    }
    cout << answer << '\n';
}

