using namespace std;

#define N 200001
using ll = long long;
const int mod = 1e9 + 7;

int n, p, a[N], f[N];
bitset<N> cant_use;

void add(int& x, int y) {
    x += y;
    if (x >= mod) {
        x -= mod;
    }
}

int up(int x) {
    int bit = 0;
    while (x) {
        bit++;
        x >>= 1;
    }
    return p - bit >= 0 ? f[p - bit] : 0;
}

bool check(int x) {
    while (1) {
        if (x & 1) {
            x >>= 1;
        } else if ((x & 3) == 0) {
            x >>= 2;
        } else {
            break;
        }
        if (!x) {
            break;
        }
        if (binary_search(a, a + n, x)) {
            return 1;
        }
    }
    return 0;
}

void solve() {
    f[0] = f[1] = 1;
    for (int i = 2; i < N; i++) {
        f[i] = f[i - 1] + f[i - 2];
        if (f[i] >= mod) {
            f[i] -= mod;
        }
    }
    for (int i = 1; i < N; i++) {
        add(f[i], f[i - 1]);
    }
    cin >> n >> p;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    sort(a, a + n);
    for (int i = 0; i < n; i++) {
        cant_use[i] = (p < 31 && a[i] >= 1 << p) || check(a[i]);
    }
    int result = 0;
    for (int i = n - 1; i >= 0; i--) {
        if (!cant_use[i]) {
            add(result, up(a[i]));
        }
    }
    cout << result;
}

