vector<pair<ll, ll>> t;



void build(int v, int l, int r, vector<ll> &arr) {

	if (l + 1 == r) {

		t[v] = {arr[l], arr[l]};

		return;

	}

	int mid = (l + r) / 2;

	build(2 * v + 1, l, mid, arr);

	build(2 * v + 2, mid, r, arr);

	t[v].first = min(t[2 * v + 1].first, t[2 * v + 2].first);

	t[v].second = max(t[2 * v + 1].second, t[2 * v + 2].second);

}



pair<ll, ll> get_min_max(int v, int l, int r, int a, int b) {

	if (b <= l || r <= a) {

		return {1000000000000000000LL, -1000000000000000000LL};

	}

	if (a <= l && r <= b) {

		return t[v];

	}

	int mid = (l + r) / 2;

	auto v1 = get_min_max(2 * v + 1, l, mid, a, b);

	auto v2 = get_min_max(2 * v + 2, mid, r, a, b);

	return {min(v1.first, v2.first), max(v1.second, v2.second)};

}



