int64 fact(int x) {
    int64 ans = 1LL;
    for (int i = 1; i <= x; i++) ans *= i;
    return ans;
}

int64 calc() {
    int digits = 0;
    for (int i = 0; i < 10; i++) digits += cur[i];

    int64 val = fact(digits);
    for (int i = 0; i < 10; i++) {
        val /= fact(cur[i]);
    }


    if (cur[0] > 0) {
        int64 over = fact(digits-1);
        cur[0]--;
        for (int i = 0; i < 10; i++) {
            over /= fact(cur[i]);
        }
        cur[0]++;
        val -= over;
    }

    return val;
}

