const int N = 200000 + 22;
vector<int> g[N];
int sz[N];

void get(int v, int pr) {
    sz[v] = 1;
    for (auto u: g[v]) {
        if (u != pr) {
            get(u, v);
            sz[v] += sz[u];
        }
    }
}

void solve() {
    int n;
    cin >> n;
    if (n == 1) {
        cout << "YES\n";
        return;
    }
    for (int i = 0; i + 1 < n; i++) {
        int v, u;
        cin >> v >> u;
        v--, u--;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    get(0, -1);
    bool ans = false;
    for (int u = 0; u < n; u++) {
        bool centr = true;
        for (auto v : g[u]) {
            int s = sz[v];
            if (s > sz[u]) {
                s = n - sz[u];
            }
            if (s > sz[0] / 2) {
                centr = false;
            }
        }
        if (!centr) {
            continue;
        }
        bool ok = true;
        vector<int> ss(n);
        function<void(int, int)> dfs = [&](int v, int p) {
            ss[v] = 1;
            vector<int> gg;
            for (auto u : g[v]) {
                if (u != p) {
                    dfs(u, v);
                    gg.push_back(u);
                }
            }
            std::sort(gg.begin(), gg.end(), [&](int a, int b) { return ss[a] < ss[b]; });
            for (auto x : gg) {
                if (ss[x] > ss[v]) {
                    ok = false;
                }
                ss[v] += ss[x];
            }
        };
        dfs(u, -1);
        ans |= ok;
    }
    cout << (ans ? "YES\n" : "NO\n");
}

