inline void push_up(int rt)

{

    segtree[rt].val=segtree[rt<<1].val+segtree[rt<<1|1].val;

}

inline void push_down(int l,int r,int rt)

{

    if(segtree[rt].lazy == -1)return ;

    int mid=l+r>>1;

    segtree[rt<<1].val=segtree[rt].lazy*(mid-l+1);

    segtree[rt<<1|1].val=segtree[rt].lazy*(r-mid);

    segtree[rt<<1].lazy=segtree[rt].lazy;

    segtree[rt<<1|1].lazy=segtree[rt].lazy;

    segtree[rt].lazy= - 1;

}

inline void build(int l,int r,int rt)

{

    segtree[rt].lazy= - 1;

    if(l==r)

    {

        segtree[rt].val=a[l];

        return ;

    }

    int mid=l+r>>1;

    build(l,mid,rt<<1);

    build(mid+1,r,rt<<1|1);

    push_up(rt);

}

inline void check(int l,int r,int rt){

    push_down( l ,r, rt);

    if(l==r){

        a[l] = segtree[rt].val;

        return ;

    }

    int mid=l+r>>1;

    check(l,mid,rt<<1);

    check(mid+1,r,rt<<1|1);

}

inline void update(int a,int b,int c,int l = 1,int r=  n,int rt = 1)

{

    if(l>b||r<a)return ;

    if(l>=a&&r<=b)

    {

        segtree[rt].val=c*(r-l+1);

        segtree[rt].lazy=c;

        return ;

    }

    push_down(l,r,rt);

    int mid=l+r>>1;

    update(a,b,c,l,mid,rt<<1);

    update(a,b,c,mid+1,r,rt<<1|1);

    push_up(rt);

}

inline int query(int a,int b,int l = 1 ,int r= n,int rt = 1)

{

    if(l>b||r<a)return 0;

    if(l>=a&&r<=b)

    return segtree[rt].val;

    push_down(l,r,rt);

    int mid=l+r>>1;

    return query(a,b,l,mid,rt<<1 )+query(a,b,mid+1,r,rt<<1|1);

}

