void build(int v, int tl, int tr)
{
	if(tl == tr)
	{
		tans[v] = 0;
		tmn[v][0] = a[tl]-tl;
		tmx[v][0] = a[tl]-tl;
		tmn[v][1] = -a[tl]-tl;
		tmx[v][1] = -a[tl]-tl;
		return;
	}
	build(v * 2, tl, (tl + tr) / 2);
	build(v * 2 + 1, (tl + tr) / 2 + 1, tr);
	Upd(v);
}

void upd(int v, int tl, int tr, int pos)
{
	if(pos < tl || tr < pos) return;
	if(tl == tr)
