constexpr bool multiple_test_cases = false;
const int mod = 998244353;

inline i64 binpow(i64 a, i64 b) {
    if (b < 0) return 0;
    i64 res = 1;
    while (b > 0) {
        if (b & 1) {
            res = res * a;
            res %= mod;
        }
        a = a * a % mod;
        b >>= 1;
    }
    return res;
}

void solve() {
    int n, m;
    std::cin >> n >> m;


    std::vector<int> a(n);
    std::vector<i64> presum(n + 1);
    for (auto &i : a) {
        std::cin >> i;
    }
    for (int i = 1; i <= n; i++) {
        presum[i] = presum[i - 1] + a[i - 1];
    }
    int cnt = 0;
    for (int i = 0, j = 0; i < n; i++) {
        while (j < n && presum[j] - presum[i] < presum[n] / 2) {
            j++;
        }
        if (j < n && (presum[j] - presum[i]) * 2 == presum[n]) {
            cnt++;
        }
    }

    int N = std::max(n, m);
    std::vector<i64> fac(N + 1, 1ll), v(N + 1, 1ll);
    for (int i = 1; i <= N; i++) {
        fac[i] = fac[i - 1] * i % mod;
    }
    v[N] = binpow(fac[N], mod - 2);
    for (int i = N - 1; i >= 0; i--)  v[i] = v[i + 1] * (i + 1) % mod;

    i64 ans = 0;
    int maxi = std::min(m, cnt);
    for (int i = 0; i <= maxi; i++) {
        i64 res1 = fac[cnt] * v[i] % mod * v[cnt - i] % mod * fac[m] % mod * v[m - i] % mod;
        i64 res2 = 1ll * (m - i) * (m - i - 1) % mod;
        i64 res3 = binpow(res2, cnt - i);
        i64 res4 = binpow(m - i, n - cnt * 2);
        ans += res1 % mod * res3 % mod * res4 % mod;
        ans %= mod;   
    }
    std::cout << ans << "\n";
}

