}p[maxn];
bool cmp(edge e1,edge e2)
{
    return e1.val<e2.val;
}
int find(int x) {return x == pre[x] ? x : pre[x] = find(pre[x]);}
ll kruskal() 
{
    for (int i = 0; i <= n; ++i) pre[i] = i;
    sort(p, p + m, cmp);
    ll res = 0;
    for (int i = 0; i < m; ++i) 
    {
        int u = find(p[i].from), v = find(p[i].to);
        if (u == v) 
            {
            continue;
        }
        p[i].used = true;
        pre[u] = v;
    }
    for (int i = 0; i <= n; ++i) pre[i] = i;
    for (int i = 0; i < m; )
    {
        int j = i;
        for (; j < m; ++j)
        {
            if (p[i].val == p[j].val) 
            {
                if (p[j].used == 0)
                {
                    int u = find(p[j].from), v = find(p[j].to);
                    if (u != v)
                     {
                        res ++;
                    }
                }
                continue;
            } else break;
        }
        for (int k = i; k < j; ++k) 
        {
            int u = find(p[k].from), v = find(p[k].to);
            if (u != v) pre[u] = v;
        }
        i = j;
    }
    return res;
}
