            for (int j = 1; j <= min(m, i - 1); ++j) {
                dp[c][j] = mul(sum(dp[p][j - 1], dp[p][j]), rev);
            }
            if (i <= m) {
                dp[c][i] = sum(dp[p][i - 1], k);
            }
        }
        cout << dp[n & 1][m] << '\n';
    }
}

