void pushup(int rt)
{
    if (ma[rt<<1]==-1 && ma[rt<<1|1]==-1)
    {
        ma[rt]=-1;mi[rt]=-1;s[rt]=0;
    }
    else if (ma[rt<<1]==-1)
    {
        ma[rt]=ma[rt<<1|1];
        mi[rt]=mi[rt<<1|1];
        s[rt]=s[rt<<1|1];
    }
    else if (ma[rt<<1|1]==-1)
    {
        ma[rt]=ma[rt<<1];
        mi[rt]=mi[rt<<1];
        s[rt]=s[rt<<1];
    }
    else
    {
        ma[rt]=ma[rt<<1|1];
        mi[rt]=mi[rt<<1];
        s[rt]=max(s[rt<<1],max(s[rt<<1|1],mi[rt<<1|1]-ma[rt<<1]));
    }
}
void update(int L,int op,int c,int l,int r,int rt)
{
    if(l==r)
    {
        if (op==1)
