void DFS(int node,int prnt,int depth){
	cur[depth].push_back(node);
	for(int i = 0 ;i < (int)g[node].size();i++){
		if(g[node][i] == prnt){
			swap(g[node][i] , g[node].back());
			g[node].pop_back();
			i--;
			continue;
		}
		DFS(g[node][i] , node , depth + 1);
	}
}

int num[N];

bool sym[N];


bool comp(int a,int b){
	return arr[a] < arr[b];
}

void solve(){
	scanf("%d",&n);
	cur[0].clear();
	for(int i = 1;i <= n;i++){
		g[i].clear();
		cur[i].clear();
	}
	for(int a,  b,  i = 0 ;i < n - 1;i++){
		scanf("%d%d",&a,&b);
		g[a].push_back(b);
		g[b].push_back(a);
	}
	DFS(1 , -1 , 0);
	for(int i = n - 1;i >= 0;i--){
		if((int)cur[i].size() == 0) continue;
		for(int node : cur[i]){
			arr[node].clear();
			for(int j = 0 ;j < (int)g[node].size();j++){
				arr[node].push_back(num[g[node][j]]);
			}
			sort(arr[node].begin(),arr[node].end());
		}
		sort(cur[i].begin(),cur[i].end(),comp);
		num[cur[i][0]] = 0;
		for(int j = 1;j < (int)cur[i].size();j++){
			num[cur[i][j]] = num[cur[i][j - 1]];
			if(arr[cur[i][j]] > arr[cur[i][j - 1]])
				num[cur[i][j]]++;
		}
		for(int node : cur[i]){
			vector< int > bad;
			while((int)arr[node].size() > 1){
				if(arr[node].back() != arr[node][(int)arr[node].size() - 2]){
					bad.push_back(arr[node].back());
					arr[node].pop_back();
					continue;
				}
				arr[node].pop_back();
				arr[node].pop_back();
