	ll nw = pw(k,n-1);
	ll invk = pw(k,mod-2);
	rep(i,1,n){
		nw = nw*invk%mod;
		memcpy(tmp,dp,sizeof(tmp));
		//repp(j,1,k)cout<<dp[j]<<' ';cout<<endl;
		pper(j,k-2,1)(dp[j] += dp[j+1]) %= mod;
		dp[1] = (dp[1]+dp[k]*k%mod)%mod;
		dp[k] = 0;
		ans += tmp[k-1]*nw%mod;ans %= mod;
		repp(j,1,k-1){
			dp[j+1] = (dp[j+1]+tmp[j]*(k-j))%mod;
		}
	}
	ll tt = 0;
	repp(i,1,k)tt += dp[i];
	assert(tt%mod==pw(k,n));
	cout<<ans<<endl;
	return 0;
}

