            if (pr == 0) {
                v[i].push_back(i);
            }
            else {
                int ret = seg1.query(1, 1, n, pr + 1, j - 1);
                if (ret != 0) {
                    v[ret].push_back(i);
                }
            }
            pr = j;
            seg1.update(1, 1, n, j, i);
        }
    }
    root[n+1] = 0;
    pst.tree.push_back({-1, -1, 0});
    pst.build(root[n+1], 1, n);
    int pr = 0;
    for (int i=n; i>=1; i--) {
        if (v[i].empty()) {
            root[i] = root[i+1];
