const int MAXN = 4000;

int TC, N, M, K;

struct UF
{
	int par[MAXN+10], val[MAXN+10];

	pii Find(int x)
	{
		if(x==par[x]) return {x, 0};
		auto [p, v] = Find(par[x]);
		v^=val[x];
		par[x]=p; val[x]=v;
		return {p, v};
	}
	bool Union(int x, int y, int v)
	{
		pii ret=Find(x);
		x=ret.first; v^=ret.second;
		ret=Find(y);
		y=ret.first; v^=ret.second;

		if(x==y) return v;
		par[x]=y; val[x]=v;
		return false;
	}
	void init()
	{
		for(int i=1; i<=N+M; i++) par[i]=i, val[i]=0;
	}
}uf;

int main()
{
	scanf("%d", &TC);
	while(TC--)
	{
		scanf("%d%d%d", &N, &M, &K);
		bool flag=true;
