int z[2 * maxn];

void getZ(const string &s) {
  for (int i = 1, l = 0, r = -1; i < sz(s); i++) {
    if (i + z[i - l] < r) {
      z[i] = z[i - l];
    } else {
      l = i;
      r = max(r, i);
      while (r < sz(s) && s[r] == s[r - l]) {
        r++;
      }
      z[i] = r - l;
    }
  }
}

int getPos(const string &s, const string &t) {
  getZ(t + "#" + s);
  for (int i = 0; i < sz(s); i++) {
    if (z[sz(t) + 1 + i] >= sz(t)) {
      return i;
    }
  }
  return -1;
}

int ls[maxn], rs[maxn];

void solve() {
  string from, to;
  for (int i = 0; i < n; i++) {
    if (s[i] == t[i]) {
      ls[i] = -1;
      rs[i] = -1;
      continue;
    }
    auto &l = ls[i], &r = rs[i];
    l = 0;
    r = sz(s[i]);
    while (s[i][l] == t[i][l]) {
      l++;
    }
    while (s[i][r - 1] == t[i][r - 1]) {
      r--;
    }
    string curs = s[i].substr(l, r - l), curt = t[i].substr(l, r - l);
    if (from.empty()) {
      from = curs;
      to = curt;
    }
    if (from != curs || to != curt) {
      printf("NO\n");
      return;
    }
  }
  while (true) {
    char c = 0;
    bool bad = false;
    for (int i = 0; i < n; i++) {
      if (ls[i] == -1) {
        continue;
      }
      if (ls[i] == 0) {
        bad = true;
        break;
      }
      if (!c) {
        c = s[i][ls[i] - 1];
      }
      if (c != s[i][ls[i] - 1]) {
        bad = true;
        break;
      }
    }
    if (bad) {
      break;
    }
    from.insert(from.begin(), c);
    to.insert(to.begin(), c);
    for (int i = 0; i < n; i++) {
      if (ls[i] == -1) {
        continue;
      }
      ls[i]--;
    }
  }
  while (true) {
    char c = 0;
    bool bad = false;
    for (int i = 0; i < n; i++) {
      if (ls[i] == -1) {
        continue;
      }
      if (rs[i] >= sz(s[i])) {
        bad = true;
        break;
      }
      if (!c) {
        c = s[i][rs[i]];
      }
      if (c != s[i][rs[i]]) {
        bad = true;
        break;
      }
    }
    if (bad) {
      break;
    }
    from += c;
    to += c;
    for (int i = 0; i < n; i++) {
      if (ls[i] == -1) {
        continue;
      }
      rs[i]++;
    }
  }
  for (int i = 0; i < n; i++) {
    int pos = getPos(s[i], from);
    if (ls[i] == -1) {
      if (pos != -1) {
        printf("NO\n");
        return;
      }
    } else {
      if (pos != ls[i]) {
        printf("NO\n");
        return;
      }
    }
  }
  printf("YES\n");
  printf("%s\n%s\n", from.c_str(), to.c_str());
}

